import { BOOK_ORDER } from '../domain/canon';
import { VERSIONS } from '../domain/versions';

/** One book: chapters[chapter - 1][verse - 1]; an empty string marks a verse missing in the source. */
type BookText = string[][];

/**
 * Reads the Bible text bundled in the extension package (public/data/<version>/<BOOK>.json,
 * generated by scripts/fetch-bibles.mjs). No network, no rate limit, works offline.
 */
export class LocalBibleSource {
  private readonly books = new Map<string, Promise<BookText>>();

  isBundled(versionId: string): boolean {
    return VERSIONS.some((v) => v.id === versionId && v.bundled);
  }

  /** Rejects if the book file is missing or unreadable, so callers can fall back to the network. */
  loadBook(versionId: string, bookId: string): Promise<BookText> {
    const id = bookId.toUpperCase();
    if (!this.isBundled(versionId) || !BOOK_ORDER.includes(id)) {
      return Promise.reject(new Error(`Not bundled: ${versionId}/${bookId}`));
    }

    const key = `${versionId}/${id}`;
    let pending = this.books.get(key);
    if (!pending) {
      pending = fetch(`/data/${versionId}/${id}.json`)
        .then((res) => {
          if (!res.ok) throw new Error(`HTTP_${res.status}`);
          return res.json() as Promise<BookText>;
        })
        .catch((err) => {
          this.books.delete(key);
          throw err;
        });
      this.books.set(key, pending);
    }
    return pending;
  }
}
